#!/usr/bin/env python3
"""Build a standalone comparison from measured output; no benchmark is rerun."""
from pathlib import Path
import json, statistics as st
root=Path(__file__).resolve().parents[2]
out=root/'output/server'
rows=json.loads((out/'ablation-results.json').read_text())
pilot=json.loads((out/'http-pilot.json').read_text())
config=json.loads((out/'ablation-config.json').read_text())
def med(engine,key): return st.median(r[key] for r in rows if r['kind']==engine)
def mib(x): return x/(1024**2)
metrics=[('Durable ingestion commit time', 'write_seconds', 's',lambda x:f'{x:.2f}'),
 ('Commit-only ingestion throughput', 'posts_per_write_second','posts/s',lambda x:f'{x:,.0f}'),
 ('Fixture update preparation + writes + interleaved reads','elapsed_with_reads_and_fixture_ops','s',lambda x:f'{x:.2f}'),
 ('Metadata read p50','query_p50_ms','ms',lambda x:f'{x:.2f}'),
 ('Metadata read p95','query_p95_ms','ms',lambda x:f'{x:.2f}'),
 ('Ingestion OS write bytes, including settle','ingestion_os_write_bytes','MiB',lambda x:f'{mib(x):,.1f}'),
 ('Final metadata files','final_files_bytes','MiB',lambda x:f'{mib(x):,.1f}'),
 ('Peak process RSS, including fixtures/JIT','process_peak_rss','MiB',lambda x:f'{mib(x):,.1f}')]
lines=['# Server and metadata-engine results','',
'Historical metadata-only ablation: the server now supports both engines. See [RocksDB_Results.md](RocksDB_Results.md) for the integrated backend measurements and [../RocksDB.md](../RocksDB.md) for usage. No live index was switched automatically.','',
'## Server pilot','',
f'The real fixture contains {pilot["posts"]:,} Float16 {pilot["dimension"]}D GTE-tiny posts in {pilot["leaves"]} existing leaves. This is an offline historical space; live ingestion keeps its existing 256D encoder. Tests used one local client, warm OS caches, a 32 MiB managed store budget, and a separate 32 MiB server buffer allowance. Each endpoint received 32 measured requests after compilation warmup, using vectors from the first 32 active posts.','',
'| Endpoint | p50 | p95 | p99 |', '| --- | ---: | ---: | ---: |']
for k,d in pilot['timings'].items(): lines.append(f'| /v1/{k} | {d["p50_ms"]:.1f} ms | {d["p95_ms"]:.1f} ms | {d["p99_ms"]:.1f} ms |')
n=pilot['timings']['nearby'];p=pilot['timings']['tree']
lines += ['',f'All nearby responses contained 25 real post IDs. Median per-request vector blocks touched: {st.median(n["blocks"]):.0f}; median vector file bytes read: {mib(st.median(n["vector_file_bytes_read"])):.1f} MiB. These are application file reads, **not physical-device read measurements**. The OS cache was warm; small application caches still evicted blocks.', '',
f'The partition pack transferred {st.median(p["response_bytes"]):,.0f} JSON bytes; the optional PPCA pack was {pilot["ppca_bytes"]:,} bytes. Nearby JSON responses were approximately {mib(st.median(n["response_bytes"]))*1024:.0f} KiB. Peak process RSS was {mib(pilot["process_memory"]["VmHWM"]):.0f} MiB, including Julia compilation/runtime and in-process HTTP clients; the managed budgets are not process limits.', '',
'Queries left the committed generation unchanged. The pilot used a fixed historical clock, so it does not measure simultaneous ingestion, source lag, daily expiry pauses or a latency SLO. Global-neighbor recall was not measured in this pilot: the endpoint deliberately samples a bounded regional pool.', '',
'## Metadata-engine ablation','',
f'Host: {config["cpu_model"]}, {config["julia"]}. Three seeds (17, 29, 43), 100,000 real identities and term contributions, and the existing 128-leaf layout. Engine processes ran sequentially with alternating engine order. Source fixtures were joined by post ID, native identity and content digest.', '',
'Both engines received the same key/value representation: identities, post locations, dense leaf posting slots, leaf/global term counts and a source cursor. SQLite used a WITHOUT ROWID key/value table, WAL and synchronous=FULL. RocksDB used sync=true WAL writes, no general compression, a 16 MiB block cache and 8 MiB write buffer. SQLite requested a 32 MiB page cache. These native cache settings do not enforce identical total memory usage.', '',
'Ingestion used durable batches of 1,024. After each batch, reads fetched 256 posting slots, 256 post locations and the first 25 term keys. This term-prefix read is **not** the server’s support-ranked vocabulary scan. Maintenance moved 128 posts to another leaf and back, then deleted 1,024 posts; each operation was one atomic batch. This exercises posting maintenance, not full density fitting or actual geometric split decisions.', '',
'Values below are medians across three runs; read percentile rows are medians of each run’s percentiles.', '',
'| Measure | SQLite | RocksDB |','| --- | ---: | ---: |']
for label,key,unit,fmt in metrics: lines.append(f'| {label} | {fmt(med("sqlite",key))} {unit} | {fmt(med("rocksdb",key))} {unit} |')
lines += ['', '| Maintenance | SQLite | RocksDB |', '| --- | ---: | ---: |']
for key,label in [('split_seconds','128-post relocation'),('merge_seconds','Merge back'),('delete_1024_seconds','1,024 deletions')]:
 vals=[st.median(r['stage'][key] for r in rows if r['kind']==kind) for kind in ['sqlite','rocksdb']]
 lines.append(f'| {label} | {1000*vals[0]:.1f} ms | {1000*vals[1]:.1f} ms |')
lines += ['', 'The first relocation includes first-call Julia compilation of the migration helper; it is not a steady-state split latency. Merge-back reuses that compiled helper. Neither includes PPCA or geometric tree work.', '',f'RocksDB’s commit-only throughput was {med("rocksdb","posts_per_write_second")/med("sqlite","posts_per_write_second"):.1f}× SQLite’s in this fixture. SQLite recorded {med("sqlite","ingestion_os_write_bytes")/med("rocksdb","ingestion_os_write_bytes"):.1f}× the ingestion OS write bytes. This supports evaluating an LSM backend, rather than assuming it will be faster.', '',
'OS write counters include checkpoint/manual compaction work at the end of ingestion. RocksDB received full manual compaction; SQLite received WAL checkpointing, **not VACUUM**. SQLite can reuse freed pages on later writes. Final file sizes should not be interpreted as equal physical-reclamation policies. OS counters are not SSD internal/NAND write amplification.', '',
'Correctness passed in all six runs: every remaining posting slot mapped back to its post/leaf, deleted identities were absent, leaf/global term counts matched reference counts, and committed cursors survived reopen. The final count digests matched across engines/seeds. These are clean-restart checks; the metadata microbenchmark does not constitute full RocksDB tree crash-recovery validation.', '',
'## Recommendation','',
'The original recommendation was to implement and validate the full RocksDB backend before switching. That implementation is now available; consult [RocksDB_Results.md](RocksDB_Results.md) for its actual results. These simplified metadata numbers alone do not justify a live switch.', '',
'For query latency, also address vector block locality and repeated term-summary scans. The measured API costs are substantially larger than either engine’s bounded metadata-read timing. Replacing SQLite alone will not remove those costs.', '',
'## Scope and reproduction','',
'- Metadata fixture preparation and term-count bookkeeping use in-memory reference structures. There is no embedding inference, vector/text payload IO, PPCA update, full keyword dictionary storage, retention chronology or long-running LSM steady state in the engine benchmark.',
'- The HTTP fixture has five broad leaves; the engine fixture uses 128. They answer different questions and must not be presented as interchangeable timings.',
'- The server suite covers API geometry, serialization, stale summaries, generation/RNG invariance, cursor pagination, concurrent HTTP, preparation failures, overload, queued deadlines, and compaction/restart. The existing ingestion crash suite additionally tests publication before files, before commit and after commit.',
'- A separate bounded combined-mode run collected live Bluesky batches, with vectors/keywords/source cursors committed together. It was a smoke test, not a sustained throughput benchmark.',
'- No cold-device, million-post, weekly-scale, concurrent-client capacity or real recommendation-quality claim follows from this run.', '',
'Run commands are in [../README.md](../README.md). [../../output/server/demo.html](../../output/server/demo.html) contains an interactive comparison. Raw runs, per-request HTTP timings and the pinned configuration live in `output/server/`. Julia dependency manifests are pinned in this folder and the server folder.', '']
# Fix relative path from benchmark documentation to repo output.
lines=[l.replace('../../output/server/demo.html','../../output/server/demo.html') for l in lines]
(root/'server/benchmark/RESULTS.md').write_text('\n'.join(lines))
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Server and metadata engines</title>
<style>body{font:16px system-ui;background:#101824;color:#dfe9f4;max-width:1100px;margin:32px auto;padding:0 24px}h1,h2{color:#fff}p{line-height:1.6;color:#c1cfde}section{background:#182536;padding:20px;border-radius:10px;margin:20px 0}select{padding:8px;background:#24364b;color:white;border:1px solid #789}label{margin-right:16px}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:10px;border-bottom:1px solid #34465b}.row{margin:24px 0}.bar{height:24px;border-radius:4px;margin:8px 0;background:#67c7b3}a{color:#95c9ff}.note{color:#ffc98b}code{color:#9eddcd}</style>
<h1>Server + SQLite / RocksDB</h1><p><a href="../rocks_optimized/demo.html">Latest: optimized RocksDB adapter results</a></p><p><a href="../adapter_profile/demo.html">New: adapter execution and allocation profiles</a></p><p>Historical metadata-only comparison. The server now supports both engines; see <a href="../rocks_backend/demo.html">the integrated backend comparison</a>. The results below are not a comparison of two complete server backends.</p>
<section><h2>100,000-post HTTP pilot</h2><p>Float16 GTE-tiny, five existing leaves, 32 MiB managed storage cache. One client, warm OS cache, 32 requests per endpoint. Nearby samples 256 candidates from up to four leaves and returns 25 IDs plus vector deltas.</p><table id="http"></table><p class="note">Not a cold-device benchmark or a latency guarantee under ingestion. Application block misses may still hit the OS cache.</p></section>
<section><h2>Metadata engines · 100,000 posts / 128 leaves</h2><label>Metric <select id="metric"><option value="posts_per_write_second">Commit-only posts/s (higher is better)</option><option value="query_p95_ms">Metadata read p95, ms (lower is better)</option><option value="ingestion_os_write_bytes">Ingestion OS writes, MiB</option><option value="final_files_bytes">Final files, MiB</option><option value="process_peak_rss">Process peak RSS, MiB (includes fixtures)</option></select></label><label>Run <select id="seed"><option value="all">Median of three runs</option><option>17</option><option>29</option><option>43</option></select></label><div id="bars"></div><p>SQLite: WAL/FULL, 32 MiB page cache. RocksDB: sync WAL, 16 MiB block cache, 8 MiB write buffer, general compression disabled. Durable batches of 1,024; reads fetch 256 candidate locations and 25 term keys.</p><p class="note">This bounded term-prefix read is not the API’s complete support-ranking scan. Native cache settings are not equal total memory caps. SQLite checkpointing and RocksDB compaction have different reclamation behavior.</p></section>
<section><h2>What the results support</h2><p>The full RocksDB backend is now implemented and tested separately. These older metadata timings do not predict full server performance. Faster metadata will not eliminate scattered vector reads or full leaf-vocabulary scans. No live store was switched automatically.</p><p>All six metadata runs passed posting, deletion, count and reopen checks. The server and existing ingestion crash checks are separate. Weekly scale and sustained mixed ingestion/query performance remain unmeasured.</p><p><a href="ablation-results.json">Raw engine results</a> · <a href="http-pilot.json">HTTP timings</a> · <a href="ablation-config.json">Pinned configuration</a> · <a href="../../server/benchmark/RESULTS.md">Full report</a></p></section>
<script>const rows=__ROWS__,pilot=__PILOT__;const median=x=>{x.sort((a,b)=>a-b);return x.length%2?x[x.length>>1]:(x[x.length/2-1]+x[x.length/2])/2};
const table=document.getElementById('http');table.innerHTML='<tr><th>Endpoint</th><th>p50</th><th>p95</th><th>p99</th></tr>'+Object.entries(pilot.timings).map(([k,v])=>'<tr><td>/v1/'+k+'</td>'+['p50_ms','p95_ms','p99_ms'].map(x=>'<td>'+v[x].toFixed(1)+' ms</td>').join('')+'</tr>').join('');
function render(){const metric=document.getElementById('metric').value,seed=document.getElementById('seed').value;const values=['sqlite','rocksdb'].map(k=>median(rows.filter(r=>r.kind===k&&(seed==='all'||r.seed===+seed)).map(r=>r[metric]))/(metric.endsWith('bytes')||metric==='process_peak_rss'?1048576:1));const max=Math.max(...values);document.getElementById('bars').innerHTML=values.map((v,i)=>'<div class="row">'+['SQLite','RocksDB'][i]+' — '+v.toLocaleString(undefined,{maximumFractionDigits:2})+'<div class="bar" style="width:'+Math.max(1,100*v/max)+'%;background:'+['#83a9ef','#67c7b3'][i]+'"></div></div>').join('')};document.getElementById('metric').onchange=render;document.getElementById('seed').onchange=render;render();</script>'''
html=html.replace('__ROWS__',json.dumps(rows)).replace('__PILOT__',json.dumps(pilot))
(out/'demo.html').write_text(html)
print('Wrote server/benchmark/RESULTS.md and output/server/demo.html')
